p='src/main/frontend/src/app/features/people/people.ts'
s=open(p).read()
s=s.replace("""// their patrons' names (sorted) and their backing: the patrons' due-totals added up, skipping n/a.
""","""// their patrons' names (sorted) and their backing: the patrons' due-totals added up, skipping n/a.
